function drawRaikouThunderTiger(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const cloudLag = breathPhase - 0.4;
  const cloudSwayX = Math.sin(cloudLag) * 3.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 32 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi tia chớp
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(18, by + 10); ctx.lineTo(28, by - 4);
  ctx.lineTo(22, by - 16); ctx.lineTo(34, by - 24);
  ctx.stroke();
  ctx.fillStyle = '#06b6d4';
  ctx.beginPath(); ctx.arc(34, by - 24, 3, 0, Math.PI * 2); ctx.fill();

  // 3. Mây giông tím
  const clx = 8 + cloudSwayX;
  ctx.fillStyle = '#a855f7';
  ctx.beginPath(); ctx.arc(clx - 6, by - 2, 10, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.arc(clx + 6, by - 6, 12, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#a855f7';
  ctx.beginPath(); ctx.arc(clx + 14, by - 2, 9, 0, Math.PI * 2); ctx.fill();

  // 4. Thân & Sọc
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.ellipse(-2, by + 12, 16 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.moveTo(-8, by + 6); ctx.lineTo(-4, by + 16); ctx.lineTo(-12, by + 14); ctx.fill();
  ctx.beginPath(); ctx.moveTo(2,  by + 6); ctx.lineTo(6,  by + 16); ctx.lineTo(-2,  by + 14); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(-2, by + 20, 10, 5, 0, 0, Math.PI * 2); ctx.fill();

  // 5. 4 Chân
  ctx.fillStyle = '#fde047';
  [-16, -8, 4, 12].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 6, 17, 2); ctx.fill();
  });
  ctx.fillStyle = '#ffffff';
  [-13, -5, 7, 15].forEach(x => {
    ctx.beginPath(); ctx.arc(x, by + 34, 3, 0, Math.PI * 2); ctx.fill();
  });

  // 6. Đầu & Má
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.arc(-12, by - 6, 14 * sX, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(-18, by - 4, 7, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-10, by - 4, 7, 0, Math.PI * 2); ctx.fill();

  // 7. Mặt nạ xanh & Giáp trán
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.moveTo(-24, by - 12); ctx.lineTo(-14, by - 6); ctx.lineTo(-20, by - 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-8,  by - 12); ctx.lineTo(-14, by - 6); ctx.lineTo(-10, by - 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.roundRect(-18, by - 16, 14, 5, 2); ctx.fill();

  // 8. Răng nanh kiếm
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-20, by - 2); ctx.lineTo(-18, by + 10); ctx.lineTo(-16, by - 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-12, by - 2); ctx.lineTo(-10, by + 10); ctx.lineTo(-8,  by - 2); ctx.fill();

  // 9. Mắt
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(-14, by - 10, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-15, by - 11, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-16, by - 10); ctx.lineTo(-12, by - 10); ctx.stroke();
  }

  ctx.restore();
}
